    /// var output = await client.PutFunctionConcurrencyAsync(input);
    ///
    /// // Expected output:
    /// var expectedOutput = new PutFunctionConcurrencyOutput(ReservedConcurrentExecutions: 100);
    /// </code>
    /// </example>
