    private static AWSGirApiServiceClientConfig WithEndpoint(
        Uri endpoint,
        AWSGirApiServiceClientConfig? config
    )
    {
        ArgumentNullException.ThrowIfNull(endpoint);
        var copy = config is null
            ? new AWSGirApiServiceClientConfig()
            : new AWSGirApiServiceClientConfig(config);
        copy.Endpoint = endpoint;
        return copy;
    }

